-- 74 Baggage Claim: bags come through the hatch every so often; the belts
-- are colliders with a `conveyor`, so they carry the bags by friction and
-- never move themselves, and the bags tumble off the far end onto a heap.
-- The oldest bags are cleared as new ones come. Generated by
-- tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/74-baggage-claim.scene"
local BAGS = { "Bc_case_red", "Bc_case_blue", "Bc_case_silver", "Bc_duffel", "Bc_backpack", "Bc_guitar", "Bc_box" }
local MAX = 26
local captions = true
local bags, next_bag, status = {}, 0.4, nil

function init(entity)
    status = Entity.find_by_name("Status")
    math.randomseed(74)
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    next_bag = next_bag - dt
    if next_bag <= 0 then
        local e = Entity.spawn_prefab(BAGS[math.random(1, #BAGS)])
        -- On the top of the sloping belt, lying along it.
        Transform.set_position(e, 515, 200)
        Transform.set_rotation(e, 0.37 + (math.random() - 0.5) * 0.1)
        bags[#bags + 1] = e
        if #bags > MAX then Entity.destroy(table.remove(bags, 1)) end
        next_bag = 1.3 + math.random() * 0.8
    end
    if status then UI.set_text(status, #bags .. " bags in the hall") end
end
